 static void metadata(ServerLevel level,RealisticGenerator g)throws Exception{var ops=RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,level.registryAccess());var meta=RealisticGenerator.CODEC.codec().encodeStart(ops,g).getOrThrow().getAsJsonObject();require(meta.get("shape_version").getAsInt()==101,"Early101 barrier");var old=meta.deepCopy();old.remove("native_ordinary_structures");old.addProperty("shape_version",100);require(RealisticGenerator.CODEC.codec().parse(ops,old).getOrThrow().nativeOrdinaryDefinition()==0,"100 keeps old ordinary bodies even unexplored");var missing=meta.deepCopy();missing.remove("native_ordinary_structures");require(RealisticGenerator.CODEC.codec().parse(ops,missing).error().isPresent(),"101 cannot silently lose body definition");try(var reader=new java.net.URLClassLoader(new java.net.URL[]{Path.of(System.getProperty("blockbranch.nativeOrdinaryPriorJar")).toUri().toURL()},NativeOrdinaryQualification.class.getClassLoader()){@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(!name.startsWith("blockbranch.realistic.RealisticGenerator"))return super.loadClass(name,resolve);synchronized(getClassLoadingLock(name)){var t=findLoadedClass(name);if(t==null)t=findClass(name);if(resolve)resolveClass(t);return t;}}}){var codec=((com.mojang.serialization.MapCodec<?>)reader.loadClass("blockbranch.realistic.RealisticGenerator").getField("CODEC").get(null)).codec();require(codec.parse(ops,old).result().isPresent()&&codec.parse(ops,meta).error().isPresent(),"Actual released100 accepts100 rejects101");}write("generator.json",meta);}
